import math
import collections

def compute_average(values):
    total = sum(values)
    count = len(values)
    return total / count

def filter_positive(data):
    result = []
    for item in data:
        if item > 0:
            result.append(item)
    return result

def transform(items):
    return [x * x for x in items]

class Calculator:
    def __init__(self):
        self.history = []

    def add_result(self, val):
        self.history.append(val)

    def get_last(self):
        return self.history[-1] if self.history else 0

data = [10, -5, 20, -3, 15]
filtered = filter_positive(data)
transformed = transform(filtered)
calc = Calculator()
