def compute(x, y):
    if x > 0:
        result = x + y
    else:
        result = str(x) - y
    return result

def validate(item):
    return isinstance(item, int)

def process(values):
    total = 0
    for v in values:
        if not validate(v):
            continue
        total += compute(v, 1)
    return total

data = [3, -2, 7, -5, 1]
